const mealUrgency={lunch:{due:720,warned:false,lateWarned:false,penaltyStep:0,lateStarted:null},dinner:{due:1020,warned:false,lateWarned:false,penaltyStep:0,lateStarted:null}};let crankyMode=false,openingRoutesStarted=false;
function scheduledDayMinutes(){
  // The visible clock advances with real elapsed seconds: 1 real second = 1 clock minute.
  // Task milestones move the day forward to a realistic meal/bedtime target when reached.
  let minutes=420+Math.floor(elapsed);
  if(tasks.lunch)minutes=Math.max(minutes,720);
  if(tasks.dinner)minutes=Math.max(minutes,1020);
  if(tasks.dinner&&tasks.bedElaina&&tasks.bedElsie&&tasks.bedEllerle)minutes=Math.max(minutes,1200);
  return minutes;
}
function mealDelay(task){const state=mealUrgency[task];return state&&state.lateStarted!==null?elapsed-state.lateStarted:0}
function updateMealUrgency(){
  for(const meal of ['lunch','dinner']){
    const state=mealUrgency[meal];
    if(!tasks[meal]&&scheduledDayMinutes()>=state.due-30&&!state.warned){
      state.warned=true;toast(`Almost time for ${meal}! Let’s get it ready.`)
    }
  }
  const current=taskOrder.find(k=>!tasks[k]);
  if(current!=='lunch'&&current!=='dinner')return;
  const state=mealUrgency[current];
  const due=state.due;
  const clockNow=scheduledDayMinutes();
  if(clockNow>=due&&state.lateStarted===null)state.lateStarted=elapsed;
  const late=state.lateStarted===null?0:elapsed-state.lateStarted;
  if(late>=35&&!state.lateWarned){
    state.lateWarned=true;toast(`It’s getting late for ${current}. The girls are getting cranky!`)
  }
  const step=Math.floor(Math.max(0,late-20)/12);
  if(step>state.penaltyStep){
    const loss=(step-state.penaltyStep)*4;
    girls.filter(g=>!g.dog&&!g.asleep).forEach(g=>{g.mood=Math.max(0,g.mood-loss);g.history=Math.max(-5,g.history-0.5*(step-state.penaltyStep))});
    state.penaltyStep=step
  }
  if(late>=85&&!crankyMode){crankyMode=true;toast('The girls are too cranky to help now. Dad will have to handle the tasks himself.') }
}

