function updateMealUrgency(){
   const dayMinutes=scheduledDayMinutes();
   for(const meal of ['lunch','dinner']){
    const state=mealUrgency[meal];
    if(!tasks[meal]&&!state.warned&&dayMinutes>=state.due-30){
     state.warned=true;
     toast(`Almost time for ${meal}! Let’s get it ready.`);
    }
   }
   const current=taskOrder.find(k=>!tasks[k]);
   if(current!=='lunch'&&current!=='dinner')return;
   const state=mealUrgency[current];
   if(dayMinutes>=state.due&&state.lateStarted===null)state.lateStarted=elapsed;
   const late=state.lateStarted===null?0:elapsed-state.lateStarted;
   if(late>=35&&!state.lateWarned){
    state.lateWarned=true;
    toast(`It’s getting late for ${current}. The girls are getting cranky!`);
   }
   const step=Math.floor(Math.max(0,late-20)/12);
   if(step>state.penaltyStep){
    const stepIncrease=step-state.penaltyStep;
    girls.filter(g=>!g.dog&&!g.asleep).forEach(g=>{
     g.mood=Math.max(0,g.mood-stepIncrease*4);
     g.history=Math.max(-5,g.history-0.5*stepIncrease);
    });
    state.penaltyStep=step;
   }
   if(late>=85&&!crankyMode){
    crankyMode=true;
    toast('The girls are too cranky to help now. Dad will have to handle the tasks himself.');
   }
  }

