const http = require('http');
const url = require('url');
const sleep = ms => new Promise(r => setTimeout(r, ms));
function get(path, method='GET') {
  return new Promise((resolve, reject) => {
    const req = http.request({host:'127.0.0.1', port:9222, path, method}, res => {
      let body=''; res.on('data', x => body+=x); res.on('end', () => resolve(body));
    }); req.on('error', reject); req.end();
  });
}
(async () => {
  const tab = JSON.parse(await get('/json/new?file:///home/runner/work/PlayGround/PlayGround/index.html', 'PUT'));
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  await new Promise((resolve,reject) => { ws.addEventListener('open',resolve,{once:true}); ws.addEventListener('error',reject,{once:true}); });
  let id=0; const pending=new Map();
  ws.addEventListener('message', e => { const m=JSON.parse(e.data); if(m.id && pending.has(m.id)) { const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result); } });
  const send=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pending.set(n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}));});
  const evalJS=async expression => (await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result.value;
  await send('Page.enable'); await send('Runtime.enable');
  await sleep(500);
  const initial=await evalJS("({time:document.querySelector('#time').textContent, intro:document.querySelector('#introShade').style.display})");
  await evalJS("document.querySelector('#startGame').click()");
  await send('Emulation.setVirtualTimePolicy',{policy:'advance',budget:270000}); await sleep(100);
  const warning=await evalJS("({time:document.querySelector('#time').textContent,toast:document.querySelector('#toast').textContent,show:document.querySelector('#toast').className})");
  await send('Emulation.setVirtualTimePolicy',{policy:'advance',budget:120000}); await sleep(100);
  const cutoff=await evalJS("({time:document.querySelector('#time').textContent,toast:document.querySelector('#toast').textContent})");
  console.log(JSON.stringify({initial,warning,cutoff},null,2));
  ws.close(); await get('/json/close/'+tab.id);
})().catch(e=>{console.error(e);process.exit(1)});

