const http=require('http');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function get(path,method='GET'){return new Promise((resolve,reject)=>{const req=http.request({host:'127.0.0.1',port:9222,path,method},res=>{let b='';res.on('data',x=>b+=x);res.on('end',()=>resolve(b))});req.on('error',reject);req.end()})}
(async()=>{
 const tab=JSON.parse(await get('/json/new?file:///tmp/opencode/game-test.html','PUT'));
 const ws=new WebSocket(tab.webSocketDebuggerUrl);
 await new Promise((resolve,reject)=>{ws.addEventListener('open',resolve,{once:true});ws.addEventListener('error',reject,{once:true})});
 let seq=0;const wait=new Map();
 ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.id&&wait.has(m.id)){const p=wait.get(m.id);wait.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result)}});
 const send=(method,params={})=>new Promise((resolve,reject)=>{const id=++seq;wait.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}))});
 const ev=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result.value;
 await send('Page.enable');await send('Runtime.enable');await sleep(250);
 const meal=await ev("(()=>{const t=window.__gameTest;t.setElapsed(270);const warning=t.snapshot();t.setElapsed(300);const due=t.snapshot();t.setElapsed(335);const late=t.snapshot();t.setElapsed(385);const cutoff=t.snapshot();return {warning,due,late,cutoff}})()");
 const bed=await ev("(()=>{const t=window.__gameTest;t.prepareBed();t.forceRefusal();t.interact();const first=t.dialog();t.clickChoice(0);return {first,afterRefusal:t.dialog()}})()");
 const hello=await ev("window.__gameTest.testGreeting()");
 console.log(JSON.stringify({meal,bed,hello},null,2));
 ws.close();await get('/json/close/'+tab.id);
})().catch(e=>{console.error(e);process.exit(1)});

