function routeBetween(fromX,fromY,x,y){const from=roomAt(fromX,fromY),to=roomAt(x,y),queue=[[from,[]]],seen=new Set([from]);let path=null;while(queue.length){const [room,links]=queue.shift();if(room===to){path=links;break}for(const link of roomLinks[room]||[]){if(!seen.has(link[0])){seen.add(link[0]);queue.push([link[0],[...links,link]])}}}const route=[];if(path)for(const link of path)route.push(link[1],link[2]);route.push([x,y]);return route}
 function setDestination(g,x,y,mode=''){g.route=routeBetween(g.x,g.y,x,y);g.tx=x;g.ty=y;g.routeMode=mode}
 function setMultiDestination(g,points,mode=''){let x=g.x,y=g.y;g.route=[];for(const [nextX,nextY] of points){g.route.push(...routeBetween(x,y,nextX,nextY));x=nextX;y=nextY}g.tx=x;g.ty=y;g.routeMode=mode}

