function requestLaundryHelp(g){openDialog(`Talk with ${g.short}`,`Choose how Dad asks ${g.short} to help with washing and drying the laundry.`,parentingStyles.map(({style,label})=>({label,run:()=>{if(respond(g,style,'laundry')){g.bubble='I’ll help with the laundry!';g.bubbleLeft=3;sendGirlToTask(g,'laundry');washTimer=6;toast('Laundry delegation accepted—cycle started.')}else requestLaundryHelp(g)}})))}
function offerTaskParenting(g,task){openDialog(`${g.short} didn’t agree`,`Try another way to ask ${g.short} to help with ${names[task].toLowerCase()}.`,parentingStyles.map(({style,label})=>({label,run:()=>{if(respond(g,style,task))completeTask(task);else offerTaskParenting(g,task)}})))}
function showerParenting(g){openDialog(`Call ${g.short} for a shower`,`${g.short}: “Do I have to shower right now?” Dad can choose how to answer.`,[...parentingStyles.map(({style,label})=>({label,run:()=>{if(respond(g,style,'showers')){g.callTask='showers';g.callStatus='showering';g.bubble='Okay, I’m coming!';g.bubbleLeft=3;sendGirlToTask(g,'showers');g.callStatus='showering';g.routeMode='shower';currentCallTask='showers'}else showerParenting(g)}})),...girls.filter(sister=>!sister.dog&&sister!==g&&!sister.asleep).map(sister=>({label:`Ask ${sister.short} to help ${g.short} shower`,run:()=>{if(respond(sister,'delegate','showers')){sister.bubble=`I’ll help ${g.short} get ready!`;sister.bubbleLeft=3;g.callTask='showers';g.callStatus='showering';g.bubble='My sister is helping me!';g.bubbleLeft=3;sendGirlToTask(g,'showers');g.callStatus='showering';g.routeMode='shower';currentCallTask='showers';toast(`${sister.short} helps ${g.short} get to her shower turn.`)}else showerParenting(g)}}))])}

