const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/home/runner/.cache/ms-playwright/chromium_headless_shell-1243/chrome-headless-shell-linux64/chrome-headless-shell', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errs = [];
  page.on('pageerror', e => errs.push(String(e)));
  await page.goto('http://localhost:3002/index.html?debug=1');
  await page.click('#startGame');
  await page.waitForFunction(() => window.__game && __game.state().opening === false, { timeout: 30000 });
  if (await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open')))
    await page.evaluate(() => document.querySelector('#dialogChoices button').click());
  await page.waitForTimeout(300);

  const state = () => page.evaluate(() => __game.state());
  const dialog = () => page.evaluate(() => ({ open: document.querySelector('#dialogShade').classList.contains('open'), title: document.querySelector('#dialogTitle').textContent, choices: [...document.querySelectorAll('#dialogChoices button')].map(b => b.textContent) }));
  const click = async (needle) => { const ok = await page.evaluate(n => { const b = [...document.querySelectorAll('#dialogChoices button')].find(b => b.textContent.includes(n)); if (!b) return false; b.click(); return true; }, needle); if (!ok) throw new Error('missing choice ' + needle + ' ' + JSON.stringify(await dialog())); await page.waitForTimeout(100); };
  const assert = (c, m) => { if (!c) throw new Error('ASSERT: ' + m); console.log('  ✓ ' + m); };

  console.log('coffee');
  await page.evaluate(() => { __game.setFocus(20); __game.setTemper(100); __game.player.x = 369; __game.player.y = 600; __game.player.awake = true; });
  await page.waitForTimeout(100);
  const note = await page.evaluate(() => document.querySelector('#dadNote').textContent);
  assert(/coffee/i.test(note), 'sidebar points Dad to coffee when focus is low');
  await page.evaluate(() => __game.interact());
  let d = await dialog();
  assert(/Coffee run/.test(d.title), 'coffee maker opens a coffee dialog');
  await click('Brew a cup');
  let st = await state();
  assert(st.focus >= 55, 'coffee restores focus');
  assert(st.coffeeCooldown > 0, 'coffee has a cooldown');
  assert(st.elapsed >= 10, 'coffee costs a little time');
  await page.evaluate(() => __game.interact());
  d = await dialog();
  assert(!d.open, 'coffee cannot be immediately repeated');

  console.log('break');
  await page.evaluate(() => { __game.setTemper(20); __game.setFocus(20); });
  await page.waitForTimeout(100);
  const labelBefore = await page.evaluate(() => document.querySelector('#break').textContent);
  assert(/Take a dad break/.test(labelBefore), 'break button is available');
  await page.evaluate(() => document.querySelector('#break').click());
  d = await dialog();
  assert(/Dad’s break/.test(d.title), 'break dialog opens');
  await click('Take the break');
  st = await state();
  assert(st.temper >= 45, 'break restores temper');
  assert(st.focus >= 45, 'break restores focus');
  assert(st.breakTimer > 0, 'break has a cooldown');
  await page.waitForTimeout(200);
  const labelAfter = await page.evaluate(() => document.querySelector('#break').textContent);
  assert(/Break ready in/.test(labelAfter), 'break button shows cooldown');

  console.log('non-compliance pressure');
  await page.evaluate(() => {
    __game.setTemper(90); __game.setFocus(20);
    __game.girls.filter(g => !g.dog).forEach(g => { g.mood = 10; g.history = -2; });
    __game.tasks.breakfast = false;
    __game.callGirls('breakfast');
  });
  await page.waitForTimeout(300);
  st = await state();
  assert(st.temper < 90, 'breakfast resistance immediately drains temper');
  const beforePassive = st.temper;
  await page.waitForTimeout(2500);
  st = await state();
  assert(st.temper < beforePassive, 'active non-compliance keeps draining temper over time');

  console.log('page errors', JSON.stringify(errs));
  assert(errs.length === 0, 'no page errors');
  await browser.close();
  console.log('MECHANICS TESTS PASSED');
})().catch(e => { console.error('FAIL', e.stack || e); process.exit(1); });

const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/home/runner/.cache/ms-playwright/chromium_headless_shell-1243/chrome-headless-shell-linux64/chrome-headless-shell', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  page.on('pageerror', e => console.log('PAGEERROR', String(e)));
  await page.goto('http://localhost:3002/index.html?debug=1');
  await page.click('#startGame');
  await page.waitForFunction(() => window.__game && __game.state().opening === false, { timeout: 30000 });
  if (await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open')))
    await page.evaluate(() => document.querySelector('#dialogChoices button').click());
  await page.waitForTimeout(300);

  const state = () => page.evaluate(() => __game.state());
  const log = async (label) => { const s = await state(); console.log(label.padEnd(28), 'temper', s.temper.toFixed(1).padStart(5), 'focus', s.focus.toFixed(1).padStart(5), 'breakCD', s.breakTimer.toFixed(0), 'coffeeCD', s.coffeeCooldown.toFixed(0), 'ended', s.ended || '-'); return s; };

  const maybeRecover = async () => {
    let s = await state();
    if (s.temper < 45) {
      const label = await page.evaluate(() => document.querySelector('#break').textContent);
      if (/Take a dad break/.test(label)) {
        await page.click('#break');
        await page.evaluate(() => { const b = [...document.querySelectorAll('#dialogChoices button')].find(b => b.textContent.includes('Take the break')); if (b) b.click(); });
        await page.waitForTimeout(150);
        console.log('  -> took a dad break');
      }
    }
    s = await state();
    if (s.focus < 45 && s.coffeeCooldown <= 0) {
      await page.evaluate(() => { __game.player.x = 369; __game.player.y = 600; __game.player.awake = true; __game.interact(); });
      const open = await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open'));
      if (open) {
        await page.evaluate(() => { const b = [...document.querySelectorAll('#dialogChoices button')].find(b => b.textContent.includes('Brew a cup')); if (b) b.click(); });
        await page.waitForTimeout(150);
        console.log('  -> brewed coffee');
      }
    }
  };

  console.log('Starting default-mood balance simulation');
  await log('start');
  const tasks = ['breakfast', 'showers', 'laundry', 'lunch', 'dishes', 'afternoon', 'dinner'];
  for (const task of tasks) {
    await maybeRecover();
    if (task === 'breakfast' || task === 'lunch' || task === 'dinner') {
      await page.evaluate(t => __game.callGirls(t), task);
      await page.waitForTimeout(200);
      // Resolve any resistance with calm redirects, as a patient player would.
      for (let i = 0; i < 30; i++) {
        const pending = await page.evaluate(() => __game.girls.filter(g => !g.dog && ['refusing', 'wandering'].includes(g.callStatus)).length);
        if (!pending) break;
        await page.evaluate(t => { __game.girls.filter(g => !g.dog && ['refusing', 'wandering'].includes(g.callStatus)).forEach(g => __game.redirectGirl(g, t)); }, task);
        await page.waitForTimeout(120);
      }
      await page.evaluate(t => __game.completeTask(t), task);
    } else if (task === 'showers') {
      await page.evaluate(() => { __game.girls.filter(g => !g.dog).forEach(g => { __game.respond(g, 'calm', 'showers'); }); __game.completeTask('showers'); });
    } else {
      const g = await page.evaluate(() => __game.girls.find(g => !g.dog).short);
      await page.evaluate(([name, t]) => {
        const g = __game.girls.find(x => x.short === name);
        for (let i = 0; i < 20 && !__game.respond(g, 'calm', t); i++) {}
        __game.completeTask(t);
      }, [g, task]);
    }
    await page.waitForTimeout(1200);
    await log(task);
  }
  await maybeRecover();
  await log('after chores');
  console.log('Final:', JSON.stringify(await state()));
  await browser.close();
})();

