  for (const vp of viewports) {
    const page = await browser.newPage({ viewport: { width: vp.width, height: vp.height } });
    const errs = [];
    page.on('pageerror', e => errs.push(String(e)));
    await page.goto('http://localhost:3002/index.html?debug=1');
    await page.click('#startGame');
    await page.waitForFunction(() => window.__game && __game.state().opening === false, { timeout: 30000 });
    if (await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open')))
      await page.evaluate(() => document.querySelector('#dialogChoices button').click());
    await page.waitForTimeout(300);

    const info = await page.evaluate(() => {
      const b = document.querySelector('#break');
      const r = b.getBoundingClientRect();
      const cx = r.left + r.width/2, cy = r.top + r.height/2;
      const top = document.elementFromPoint(cx, cy);
      return { rect: {x:r.left,y:r.top,w:r.width,h:r.height}, cx, cy, topTag: top ? top.tagName : null, topId: top ? top.id : null, topClass: top ? top.className : null, disabled: b.disabled, inViewport: r.top>=0 && r.left>=0 && r.bottom<=window.innerHeight && r.right<=window.innerWidth };
    });
