    console.log('break rect:', JSON.stringify(info.rect), 'inViewport:', info.inViewport, 'disabled:', info.disabled);
    console.log('elementFromPoint center:', info.topTag, info.topId, String(info.topClass).slice(0,60));

    // set temper low, try clicking
    await page.evaluate(() => __game.setTemper(20));
    await page.waitForTimeout(100);
    await page.click('#break').catch(e => console.log('click error:', e.message));
    await page.waitForTimeout(200);
    const opened = await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open'));
    const title = await page.evaluate(() => document.querySelector('#dialogTitle').textContent);
    console.log('after click: dialog open=', opened, 'title=', title);
    if (opened) await page.evaluate(() => document.querySelector('#dialogChoices button').click());
    await page.waitForTimeout(200);

    // Test: dialog open, try to click break
    await page.evaluate(() => __game.openDialog('Test dialog','A dialog is open.',[{label:'Close',run:()=>{}}]));
    await page.waitForTimeout(100);
    const before = await page.evaluate(() => document.querySelector('#dialogTitle').textContent);
    let clicked = false;
    try { await page.click('#break', { timeout: 2000 }); clicked = true; } catch (e) { clicked = false; }
    await page.waitForTimeout(200);
    const afterTitle = await page.evaluate(() => document.querySelector('#dialogTitle').textContent);
    console.log('during dialog: click registered=', clicked, 'title before=', before, 'title after=', afterTitle);
    if (await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open')))
      await page.evaluate(() => document.querySelector('#dialogChoices button').click());
    await page.waitForTimeout(100);

    // Test at 0 temper
    await page.evaluate(() => { __game.setTemper(0); __game.setFocus(20); });
    await page.waitForTimeout(100);
    const ended = await page.evaluate(() => __game.state().ended);
    let clicked2 = false;
    try { await page.click('#break', { timeout: 2000 }); clicked2 = true; } catch (e) { clicked2 = false; }
    await page.waitForTimeout(200);
    const ended2 = await page.evaluate(() => __game.state().ended);
    const opened2 = await page.evaluate(() => document.querySelector('#dialogShade').classList.contains('open'));
    console.log('at 0 temper: ended before=', ended, 'click registered=', clicked2, 'ended after=', ended2, 'dialog open=', opened2);

    console.log('page errors:', errs.length ? errs.join('; ') : 'none');
    await page.close();
  }
  await browser.close();
})();

