  // 1. In-dialog break choice present?
  await page.evaluate(() => __game.openDialog('Test dialog','A dialog is open.',[{label:'Close',run:()=>{}}]));
  await page.waitForTimeout(100);
  const labels = await page.evaluate(() => [...document.querySelectorAll('#dialogChoices button')].map(b=>b.textContent));
  console.log('dialog choices:', labels);
  const hasBreak = labels.some(l => /dad break/i.test(l));
  console.log('has in-dialog break choice:', hasBreak);

  // 2. Click in-dialog break -> opens break dialog
  await page.evaluate(() => { const b = [...document.querySelectorAll('#dialogChoices button')].find(b=>/dad break/i.test(b.textContent)); b.click(); });
  await page.waitForTimeout(200);
  const title = await page.evaluate(() => document.querySelector('#dialogTitle').textContent);
  console.log('after in-dialog break click, title:', title);

  // 3. Take the break
  await page.evaluate(() => { const b = [...document.querySelectorAll('#dialogChoices button')].find(b=>/Take the break/i.test(b.textContent)); b.click(); });
  await page.waitForTimeout(200);
  const st = await page.evaluate(() => __game.state());
  console.log('after break: temper=', st.temper.toFixed(1), 'focus=', st.focus.toFixed(1), 'breakTimer=', st.breakTimer.toFixed(1), 'ended=', st.ended);

  // 4. Keyboard B while a dialog is open
  await page.evaluate(() => __game.setTemper(20));
  await page.evaluate(() => __game.openDialog('Another dialog','Open again.',[{label:'Close',run:()=>{}}]));
  await page.waitForTimeout(100);
  await page.keyboard.press('b');
  await page.waitForTimeout(200);
  const title2 = await page.evaluate(() => document.querySelector('#dialogTitle').textContent);
  console.log('after pressing B during dialog, title:', title2);

  // 5. Cooldown feedback via sidebar button
  await page.evaluate(() => { if (document.querySelector('#dialogShade').classList.contains('open')) document.querySelector('#dialogChoices button').click(); });
  await page.waitForTimeout(200);
  const before = await page.evaluate(() => __game.state().breakTimer);
  await page.click('#break');
  await page.waitForTimeout(200);
  const toast = await page.evaluate(() => document.querySelector('#toast').textContent);
  console.log('cooldown remaining:', before.toFixed(1), 'toast:', toast);

  // 6. Game over: break gives feedback
  await page.evaluate(() => { __game.setTemper(0); });
  await page.waitForTimeout(100);
  await page.click('#break');
  await page.waitForTimeout(200);
  const toast2 = await page.evaluate(() => document.querySelector('#toast').textContent);
  console.log('at game over toast:', toast2);

  await browser.close();
  console.log('BREAK DIAG DONE');
})();

